import React, { useState } from "react";
import "../styles/Chat.css";

const Chat = () => {

    const [input, setInput] = useState("");

    const [normalMessages, setNormalMessages] = useState([]);
    const [forgetMessages, setForgetMessages] = useState([]);

    const sendMessage = () => {
        if (!input) return;

        const userMsg = { text: input, sender: "user" };

        // NORMAL AI
        setNormalMessages(prev => [...prev, userMsg]);

        // FORGETTING AI
        setForgetMessages(prev => [...prev, userMsg]);

        // Fake AI responses
        setTimeout(() => {
            setNormalMessages(prev => [
                ...prev,
                { text: "I remember everything you said 🧠", sender: "ai" }
            ]);

            setForgetMessages(prev => [
                ...prev,
                { text: "I may forget this later 🤖", sender: "ai" }
            ]);
        }, 1000);

        setInput("");
    };

    return (
        <div className="chat-page">

            {/* LEFT SIDE */}
            <div className="chat-panel">

                <h2>Normal AI 🤖</h2>
                <p className="subtitle">Remembers everything</p>

                <div className="chat-box">
                    {normalMessages.map((msg, i) => (
                        <div key={i} className={msg.sender}>
                            {msg.text}
                        </div>
                    ))}
                </div>

            </div>

            {/* RIGHT SIDE */}
            <div className="chat-panel">

                <h2>Forgetting AI 🧠</h2>
                <p className="subtitle">Forgets intelligently</p>

                <div className="chat-box">
                    {forgetMessages.map((msg, i) => (
                        <div key={i} className={msg.sender}>
                            {msg.text}
                        </div>
                    ))}
                </div>

            </div>

            {/* INPUT (COMMON) */}
            <div className="input-container">
                <input
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    placeholder="Ask something..."
                />
                <button onClick={sendMessage}>Send</button>
            </div>

        </div>
    );
};

export default Chat;
